const MAPS_API_KEY = 'YOUR_GOOGLE_MAPS_API_KEY'; // slot for real key

function buildMapsUrl(lat, lng, zoom = 19, size = 400) {
  return `https://maps.googleapis.com/maps/api/staticmap?center=${lat},${lng}&zoom=${zoom}&size=${size}x${size}&maptype=satellite&key=${MAPS_API_KEY}`;
}

// ── Geocode via Google (no-key fallback: Nominatim) ──────────
async function geocodeAddress(address) {
  try {
    const url = `https://nominatim.openstreetmap.org/search?q=${encodeURIComponent(address)}&format=json&limit=1`;
    const res = await fetch(url, {
      headers: {
        'Accept-Language': 'en',
        'User-Agent': 'CleanEstimatePro/1.0'
      }
    });
    const json = await res.json();
    if (json?.length) return {
      lat: parseFloat(json[0].lat),
      lng: parseFloat(json[0].lon),
      display: json[0].display_name
    };
    return null;
  } catch {
    return null;
  }
}

